$ErrorActionPreference = 'Stop'
opencli --profile 74u3g3us browser wt eval "(() => { const s = window.__dshWorktable && window.__dshWorktable.splitStore; return s && s.active ? JSON.stringify({ right: s.geom && s.geom.right, chatW: s.chatW, bar: BARH_dummy || undefined }) : 'no-split'; })()"
