opencli --profile 74u3g3us browser wt eval "(() => { const s = window.__dshWorktable && window.__dshWorktable.splitStore; if (!s || !s.active || !s.geom) return 'no-active'; const x = s.geom.right - s.chatW - 2; const y = (s.geom.top + s.geom.bottom) / 2; const el = document.elementFromPoint(x, y); const arr = []; let n = el; let d = 0; while (n && d < 3) { arr.push(n.tagName + '.' + String(n.className).split(' ').slice(0,3).join('.')); n = n.parentElement; d++; } return JSON.stringify({ x: Math.round(x), y: Math.round(y), hit: arr }); })()"
