opencli --profile 74u3g3us browser wt eval "(() => { const s = window.__dshWorktable && window.__dshWorktable.splitStore; if (!s || !s.geom) return 'no'; const x = s.geom.right - s.chatW - 2; const y = (s.geom.top + s.geom.bottom) / 2; const el = document.elementFromPoint(x, y); return el ? (el.closest('.dsh-wt_splitDivider') ? 'hit-divider' : el.closest('[data-phase]') ? 'hit-host-chat' : el.closest('.dsh-wt_pane') ? 'hit-pane' : 'hit-other:' + el.tagName) : 'null'; })()"
